import numpy as np

# =====================================================================
# EDITABLE: implement run_causal_discovery below
# =====================================================================
def run_causal_discovery(X: np.ndarray) -> np.ndarray:
    from sklearn.linear_model import LassoLarsIC
    from sklearn.utils import check_array

    X = check_array(X)
    n, d = X.shape
    eps = 1e-8
    Z = (X - X.mean(0)) / (X.std(0) + eps)

    def dep(a, b):
        a = (a - a.mean()) / (a.std() + eps)
        b = (b - b.mean()) / (b.std() + eps)
        return abs((np.tanh(a) * b).mean()) + abs((a * np.tanh(b)).mean()) + 0.5 * abs(((a ** 3) * b).mean())

    def resid(y, x):
        return y - x * ((y @ x) / (x @ x + eps))

    def direct():
        def ent(u):
            return (1 + np.log(2 * np.pi)) / 2 - 79.047 * (np.mean(np.log(np.cosh(u))) - 0.37457) ** 2 - 7.4129 * (np.mean(u * np.exp(-(u ** 2) / 2))) ** 2
        U, K, Xw = np.arange(d), [], Z.copy()
        while len(U) > 1:
            scores = []
            for i in U:
                xi = (Xw[:, i] - Xw[:, i].mean()) / (Xw[:, i].std() + eps)
                M = 0.0
                for j in U:
                    if i == j:
                        continue
                    xj = (Xw[:, j] - Xw[:, j].mean()) / (Xw[:, j].std() + eps)
                    ri, rj = resid(xi, xj), resid(xj, xi)
                    dm = (ent(xj) + ent(ri / (ri.std() + eps))) - (ent(xi) + ent(rj / (rj.std() + eps)))
                    M += min(0.0, dm) ** 2
                scores.append(-M)
            m = int(U[np.argmax(scores)])
            for i in U:
                if i != m:
                    Xw[:, i] = resid(Xw[:, i], Xw[:, m])
            K.append(m)
            U = U[U != m]
        return K + list(U)

    def pairwise():
        win = np.zeros(d)
        for i in range(d):
            for j in range(i + 1, d):
                s_ij = dep(Z[:, i], resid(Z[:, j], Z[:, i]))
                s_ji = dep(Z[:, j], resid(Z[:, i], Z[:, j]))
                win[i] += s_ji - s_ij
                win[j] += s_ij - s_ji
        return list(np.argsort(-win))

    def oscore(K):
        E = np.column_stack([Z[:, k] - (Z[:, K[:t]] @ np.linalg.lstsq(Z[:, K[:t]], Z[:, k], rcond=None)[0] if t else 0.0) for t, k in enumerate(K)])
        return sum(dep(E[:, a], E[:, b]) for a in range(d) for b in range(a))

    K1, K2 = direct(), pairwise()
    s1, s2 = oscore(K1), oscore(K2)
    K1, K2 = direct(), pairwise()
    s1, s2 = oscore(K1), oscore(K2)
    r1, r2 = np.empty(d), np.empty(d)
    r1[K1], r2[K2] = np.arange(d), np.arange(d)
    K3 = list(np.argsort(r1 / (s1 + eps) + r2 / (s2 + eps)))
    K = K1 if d <= 60 else min((K1, K3) if d <= 80 else (K1, K2, K3), key=oscore)

    B = np.zeros((d, d))
    tau = max(2.5, np.sqrt(2.5 * np.log(d + 1)))
    mag = 0.02 + np.sqrt(np.log(d + 1) / (4 * (n + 1)))
    for t, k in enumerate(K):
        if t == 0:
            continue
        pa = np.array(K[:t])
        P, y = Z[:, pa], Z[:, k]
        try:
            sel = np.abs(LassoLarsIC(criterion='bic', fit_intercept=False).fit(P, y).coef_) > 1e-10
        except Exception:
            beta0 = np.linalg.lstsq(P, y, rcond=None)[0]
            sel = np.abs(beta0) > np.sqrt(np.log(d + 1) / (n + 1))
        pa = pa[sel]
        if pa.size == 0:
            continue
        Ps = Z[:, pa]
        for _ in range(3):
            beta = np.linalg.lstsq(Ps, y, rcond=None)[0]
            r = y - Ps @ beta
            sigma2 = (r @ r) / max(n - Ps.shape[1], 1)
            se = np.sqrt(np.maximum(np.diag(np.linalg.pinv(Ps.T @ Ps)) * sigma2, eps))
            keep = np.abs(beta) / (se + eps) > tau
            if keep.all():
                break
            if not keep.any():
                pa = np.array([], dtype=int)
                break
            Ps, pa = Ps[:, keep], pa[keep]
        if pa.size:
            beta = np.linalg.lstsq(Ps, y, rcond=None)[0]
            keep = np.abs(beta) > mag
            if np.any(keep):
                B[k, pa[keep]] = beta[keep]
    return B
